    if (y < 100) { const x = d; d = mth; mth = x; y += 2000; }  // 'm/d/aa': planilha virou texto no padrao do Excel em ingles
    return mth >= 1 && mth <= 12 && d >= 1 && d <= 31 ? y + '-' + p2(mth) + '-' + p2(d) : '';
  }
  return '';
}
function fupRegistro(row, fonte, visto) {
  const lin = {};
  for (const [k, v] of Object.entries(row || {})) lin[String(k).trim().toUpperCase()] = v;
  const rec = {};
  for (const [col, key] of Object.entries(FUP_CAMPOS)) {
    let v = lin[col];
    if (FUP_DATAS.has(key)) v = fupData(v);
    else if (typeof v === 'string') v = v.replace(/\s+/g, ' ').trim();
    if (v !== null && v !== undefined && v !== '') rec[key] = v;
  }
  const chave = fupChave(rec.conhecimento) || fupChave(rec.ref) || fupChave(rec.wfadim);
  if (!chave) return null;
  if (typeof rec.qtd === 'string' && /^\d+$/.test(rec.qtd)) rec.qtd = Number(rec.qtd);
  if (typeof rec.cif === 'string') { const n = Number(rec.cif.replace(/,/g, '')); if (isNaN(n)) delete rec.cif; else rec.cif = n; }
  rec.fonte = fonte; rec.visto = visto;
  return [chave, rec];
}
// ===== Planilha inteira do relatorio (pgl_relatorios.planilha) =====
const PGL_RELATORIOS = {
  fisia: {titulo: 'Follow Up · Fisia', assunto: 'Relatório de Follow Up - FISIA'},
  zelus: {titulo: 'Follow Up · Fisia / Zelus', assunto: 'Relatório de Follow Up - Fisia / Zelus'},
  sbf: {titulo: 'Follow Up · SBF (Centauro)', assunto: 'Relatório de Follow Up - SBF'},
};
const DATA_COL = /^(DT |DATA|EMBARQUE NA ORIGEM|PREVISAO|CHEGADA|PRESENCA|REGISTRO DI|DESEMBARACO|INSPECAO|ENTREGA DA|ENTREGA DOC|NECESSIDADE|DATA_)/i;
function pglTexto(v) {
  if (v === undefined || v === null) return null;
  if (typeof v === 'string') { const t = v.trim(); return t === '' ? null : t; }
  return v;
}
// Itens do 'Extract From File' (um objeto por linha, chaves = 1a linha da planilha) -> matriz com a 1a linha de volta
function pglMatriz(objs) {
  const chaves = [];
  for (const o of objs) for (const k of Object.keys(o || {})) if (!chaves.includes(k)) chaves.push(k);
  return [chaves.map(k => /^__EMPTY(_\d+)?$/.test(k) ? '' : k), ...objs.map(o => chaves.map(k => (o || {})[k]))];
}
function pglPlanilha(matriz) {
  let ini = -1;
  for (let i = 0; i < Math.min(15, matriz.length); i++) {
    const s = new Set(matriz[i].map(c => String(c == null ? '' : c).trim().toUpperCase()));
    if (s.has('MODAL') && s.has('PROCESSO')) { ini = i; break; }
  }
  if (ini < 0) throw new Error('cabeçalho do FUP não encontrado (sem as colunas MODAL e PROCESSO)');
  const cab = matriz[ini].map(c => String(c == null ? '' : c).trim());
  while (cab.length && !cab[cab.length - 1]) cab.pop();
  const datas = cab.map(c => DATA_COL.test(c));
  const linhas = [];
  for (const r of matriz.slice(ini + 1)) {
    const lin = cab.map((_, j) => { const v = r[j]; if (datas[j] && v !== null && v !== undefined && v !== '') return fupData(v) || pglTexto(v); return pglTexto(v); });
    if (lin.some(v => v !== null && v !== '')) linhas.push(lin);
  }
  return {colunas: cab, linhas};
}
function pglRegistros(colunas, linhas, fonte, visto) {
  const out = {};
  for (const lin of linhas) { const row = {}; colunas.forEach((c, j) => { row[c] = lin[j]; }); const par = fupRegistro(row, fonte, visto); if (par) out[par[0]] = par[1]; }
  return out;
}
function pglTipo(assunto) {
  const a = String(assunto || '').toUpperCase();
  return a.includes('ZELUS') ? 'zelus' : a.includes('FISIA') ? 'fisia' : a.includes('SBF') ? 'sbf' : '';
}

// ===== Planilha inteira + historico por processo, gravados no arquivo da pasta do sistema =====
