est.relatorios = est.relatorios || {}; est.processos = est.processos || {};
const info = PGL_RELATORIOS[meta.tipo] || {titulo: meta.tipo, assunto: ''};
est.relatorios[meta.tipo] = {titulo: info.titulo, assunto: info.assunto, msg: meta.msg, recebido_em: meta.recebido_em,
                             arquivo: meta.arquivo, colunas, linhas};
if (meta.tipo === 'fisia' || meta.tipo === 'zelus') Object.assign(est.processos, pglRegistros(colunas, linhas, meta.tipo, meta.recebido_em));
est.versao = 1;
est.atualizado_em = new Date().toISOString();
